def is_triangle_free(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return False
    return True

def min_degree(edges, n):
    deg = [0] * n
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    return min(deg) if n > 0 else 0

def chromatic_number(edges, n, max_colors=5):
    # Check if graph can be colored with max_colors colors
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = [False] * (max_colors + 1)
        for nb in adj[v]:
            if colors[nb] != -1:
                used[colors[nb]] = True
        for c in range(1, max_colors + 1):
            if not used[c]:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    if backtrack(0):
        return max(colors)
    return None  # Not colorable with max_colors

